export function getFlowProfile(artistId: string): FlowProfile | null {
  return FLOW_PROFILES[artistId] ?? ADDITIONAL_FLOW_PROFILES[artistId] ?? null;
}

export function getCadenceLabel(cadence: CadenceType): string {
  const labels: Record<CadenceType, string> = {
    triplet: "Triplet (3 por beat)",
    staccato: "Staccato (sílabas secas)",
    legato: "Legato (arrastrado)",
    swing: "Swing (laid-back)",
    syncopated: "Syncopated (off-beat)",
    rapid_fire: "Rapid Fire (ametralladora)",
    melodic_flow: "Melodic Flow (cantado)",
    chaotic: "Chaotic (impredecible)",
    conversational: "Conversational (natural)",
    free: "Free (libre)",
  };
  return labels[cadence] ?? cadence;
}

export function getBreathInstruction(profile: FlowProfile): string {
  return `Inserta un ${profile.breathStyle} cada ${profile.breathEveryBars} barras aproximadamente, en el punto natural de respiración. Esto hace que Suno genere pausas vocales realistas.`;
}

